RunEv44060040 <- function ()
{
	// Play the event scene and wait for it
	CMND_BTL_SET_EVPARAM(44060040);
	suspend();
	// Unlock a technique, clear the on-screen objective
	CMND_SKILL_UNLOCK("para_cp0008", "whd0008");
	CMND_BTL_SET_PURPOSE(0, -1, false, 0);
	CMND_BTL_SET_PURPOSETEXT(false, 0, 0);
	CMND_BTL_SET_MATCH_EFFECT(0, 0);
	// Record story progress, then stop the match
	CMND_SET_GLOBAL_BIT_FLAG(518, 1);
	CMND_SET_GLOBAL_BIT_FLAG(62);
	CMND_BTL_END_MATCH();
};

// Set a story flag only if the player's team (0) is ahead
local point_self = CMND_BTL_GET_POINT(0);
local point_enemy = CMND_BTL_GET_POINT(1);

if (point_self > point_enemy)
{
	CMND_SET_GLOBAL_BIT_FLAG(1375, 1);
}

// Keep the match history, then end the match
CMND_BTL_SAVE_HISTORY();
CMND_BTL_END_MATCH();
